@formatDateTime(
    addDays(
        startOfMonth(utcNow()),
        sub(
            min(
                int(outputs('Get_assignment_row_by_ID')?['body/new_dayofmonthformonthlyinvoicegrouping']),
                div(
                    sub(
                        ticks(addDays(startOfMonth(utcNow()), 31)),
                        ticks(startOfMonth(utcNow()))
                    ),
                    864000000000
                )
            ),
            1
        )
    ),
    'yyyy-MM-ddTHH:mm:ss.fffffffZ'
)
